From 38fc812831e7fbd425164c5be7c53c1ef6face03 Mon Sep 17 00:00:00 2001
From: Valentine Sinitsyn <valentine.sinitsyn@gmail.com>
Date: Fri, 4 Jul 2014 00:17:24 +0600
Subject: [PATCH] x86: Never write to vmcb->rax from now on

This commit fixes subtle bug introduced with commit 8b7fb51: vmcb->rax
is overwritten with guest_regs->rax value when a guest resumes, so one
should never modify vmcb->rax as that value will be lost.

diff --git a/hypervisor/arch/x86/svm.c b/hypervisor/arch/x86/svm.c
index 363efdc9..13ed4857 100644
--- a/hypervisor/arch/x86/svm.c
+++ b/hypervisor/arch/x86/svm.c
@@ -721,37 +721,37 @@ static void svm_handle_hypercall(struct registers *guest_regs,
 	if ((!(vmcb->efer & EFER_LMA) &&
 	      vmcb->rflags & X86_RFLAGS_VM) ||
 	     (vmcb->cs.selector & 3) != 0) {
-		vmcb->rax = -EPERM;
+		guest_regs->rax = -EPERM;
 		return;
 	}

-	switch (vmcb->rax) {
+	switch (guest_regs->rax) {
 		case JAILHOUSE_HC_DISABLE:
-			vmcb->rax = shutdown(cpu_data);
-			if (vmcb->rax == 0)
+			guest_regs->rax = shutdown(cpu_data);
+			if (guest_regs->rax == 0)
 				svm_cpu_deactivate_vmm(guest_regs, cpu_data);
 			break;
 		case JAILHOUSE_HC_CELL_CREATE:
-			vmcb->rax = cell_create(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_create(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CELL_DESTROY:
-			vmcb->rax = cell_destroy(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_destroy(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_HYPERVISOR_GET_INFO:
-			vmcb->rax = hypervisor_get_info(cpu_data,
+			guest_regs->rax = hypervisor_get_info(cpu_data,
 					guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CELL_GET_STATE:
-			vmcb->rax = cell_get_state(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_get_state(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CPU_GET_STATE:
-			vmcb->rax = cpu_get_state(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cpu_get_state(cpu_data, guest_regs->rdi);
 			break;
 		default:
 			printk("CPU %d: Unknown vmcall %d, RIP: %p\n",
-					cpu_data->cpu_id, vmcb->rax,
+					cpu_data->cpu_id, guest_regs->rax,
 					vmcb->rip - X86_INST_LEN_VMCALL);
-			vmcb->rax = -ENOSYS;
+			guest_regs->rax = -ENOSYS;
 			break;
 	}
 }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by directly modifying `vmcb->rax` with values from `guest_regs->rax` during guest resume operations. This led to the loss of the original `vmcb->rax` value, which is critical for the hypervisor's functionality, as it should not be altered when the guest is resumed. The incorrect handling of the `rax` register could result in unexpected behavior or errors in the guest's execution context.

        Commit message:
        x86: Never write to vmcb->rax from now on

This commit fixes subtle bug introduced with commit 8b7fb51: vmcb->rax
is overwritten with guest_regs->rax value when a guest resumes, so one
should never modify vmcb->rax as that value will be lost.  

        Patch:
          */
 static void svm_handle_hypercall(struct registers *guest_regs,
 				 struct per_cpu *cpu_data)
 {
 	struct vmcb *vmcb = &cpu_data->vmcb;

 	svm_skip_emulated_instruction(X86_INST_LEN_VMCALL, vmcb);

 	if ((!(vmcb->efer & EFER_LMA) &&
 	      vmcb->rflags & X86_RFLAGS_VM) ||
 	     (vmcb->cs.selector & 3) != 0) {
-		vmcb->rax = -EPERM;
+		guest_regs->rax = -EPERM;
 		return;
 	}

-	switch (vmcb->rax) {
+	switch (guest_regs->rax) {
 		case JAILHOUSE_HC_DISABLE:
-			vmcb->rax = shutdown(cpu_data);
-			if (vmcb->rax == 0)
+			guest_regs->rax = shutdown(cpu_data);
+			if (guest_regs->rax == 0)
 				svm_cpu_deactivate_vmm(guest_regs, cpu_data);
 			break;
 		case JAILHOUSE_HC_CELL_CREATE:
-			vmcb->rax = cell_create(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_create(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CELL_DESTROY:
-			vmcb->rax = cell_destroy(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_destroy(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_HYPERVISOR_GET_INFO:
-			vmcb->rax = hypervisor_get_info(cpu_data,
+			guest_regs->rax = hypervisor_get_info(cpu_data,
 					guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CELL_GET_STATE:
-			vmcb->rax = cell_get_state(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cell_get_state(cpu_data, guest_regs->rdi);
 			break;
 		case JAILHOUSE_HC_CPU_GET_STATE:
-			vmcb->rax = cpu_get_state(cpu_data, guest_regs->rdi);
+			guest_regs->rax = cpu_get_state(cpu_data, guest_regs->rdi);
 			break;
 		default:
 			printk("CPU %d: Unknown vmcall %d, RIP: %p\n",
-					cpu_data->cpu_id, vmcb->rax,
+					cpu_data->cpu_id, guest_regs->rax,
 					vmcb->rip - X86_INST_LEN_VMCALL);
-			vmcb->rax = -ENOSYS;
+			guest_regs->rax = -ENOSYS;
 			break;
 	}
 }



